param([Parameter(Mandatory=$true)][string]$RunRoot,[Parameter(Mandatory=$true)][string]$WorkingDirectory,[Parameter(Mandatory=$true)][string[]]$SourcePaths,[Parameter(Mandatory=$true)][string]$BuildCaptureDir,[Parameter(Mandatory=$true)][string]$TestCaptureDir)
$ErrorActionPreference='Stop';$RunRoot=[IO.Path]::GetFullPath($RunRoot);$cwd=[IO.Path]::GetFullPath($WorkingDirectory);$env:M0_RUN_EVIDENCE_ROOT=$RunRoot;$out=Join-Path $RunRoot 'verify';New-Item -ItemType Directory -Path $out -Force|Out-Null
function Head{$h=& git -C $cwd rev-parse HEAD;if($LASTEXITCODE -ne 0){throw 'git rev-parse failed'};return $h.Trim()}
function Snap([string]$name){$rows=@(foreach($rel in $SourcePaths){$p=Join-Path $cwd $rel;$b=[IO.File]::ReadAllBytes($p);$lf=[Text.Encoding]::UTF8.GetBytes([Text.Encoding]::UTF8.GetString($b).Replace("`r`n","`n"));$blob=& git -C $cwd hash-object -- $rel;if($LASTEXITCODE -ne 0){throw 'git hash-object failed'};[pscustomobject]@{path=$rel;size=$b.Length;sha256=([Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($b)).ToLowerInvariant());lf_sha256=([Convert]::ToHexString([Security.Cryptography.SHA256]::HashData($lf)).ToLowerInvariant());git_blob=$blob.Trim()}});$rows|ConvertTo-Json -Depth 4|Set-Content -LiteralPath (Join-Path $out "$name-source.json") -Encoding utf8;return ,$rows}
$start=[DateTime]::UtcNow.ToString('o');$headBefore=Head;$ownBefore=Snap 'before';$exit=0;$failure=$null;$verification=$null
try {
 $buildDir=[IO.Path]::GetFullPath($BuildCaptureDir);$testDir=[IO.Path]::GetFullPath($TestCaptureDir);$bmPath=Join-Path $buildDir 'build-output-manifest.json';$bm=Get-Content -LiteralPath $bmPath -Raw|ConvertFrom-Json;$bc=Get-Content -LiteralPath (Join-Path $buildDir 'command.json') -Raw|ConvertFrom-Json;$tc=Get-Content -LiteralPath (Join-Path $testDir 'command.json') -Raw|ConvertFrom-Json
 $manifestDigest=(Get-FileHash -Algorithm SHA256 -LiteralPath $bmPath).Hash.ToLowerInvariant();$sidecar=[IO.File]::ReadAllText("$bmPath.sha256").Trim();if($manifestDigest -ne $sidecar -or $manifestDigest -ne $bc.build_output_manifest_sha256){throw 'manifest-digest-binding-failed'}
 $expectedHead='4bc2ebf837b7478c57519c2421b7b95f288108f5';$sourcePin='55bc0ea1605952baa967ec81c6a4cc90564879c6';if($headBefore -ne $expectedHead -or $bc.actual_head_before -ne $expectedHead -or $bc.actual_head_after -ne $expectedHead -or $tc.actual_head_before -ne $expectedHead -or $tc.actual_head_after -ne $expectedHead -or $bm.actual_head_before -ne $expectedHead -or $bm.actual_head_after -ne $expectedHead){throw 'actual-head-binding-failed'}
 if($bc.exit_code -ne 0 -or $tc.exit_code -ne 0 -or $bm.exit_code -ne 0 -or $bm.capture_id -ne $bc.capture_id -or $tc.build_capture_id -ne $bc.capture_id -or $tc.build_manifest_sha256 -ne $manifestDigest){throw 'capture-id-or-exit-binding-failed'}
 if([DateTime]::Parse($bm.build_finished_utc).ToUniversalTime() -gt [DateTime]::Parse($bm.manifest_created_utc).ToUniversalTime() -or [DateTime]::Parse($bm.manifest_created_utc).ToUniversalTime() -ge [DateTime]::Parse($tc.started_utc).ToUniversalTime()){throw 'build-finished-manifest-test-order-invalid'}
 $srcBefore=@(Get-Content -LiteralPath (Join-Path $buildDir 'before-source.json') -Raw|ConvertFrom-Json);$srcAfter=@(Get-Content -LiteralPath (Join-Path $buildDir 'after-source.json') -Raw|ConvertFrom-Json);$testBefore=@(Get-Content -LiteralPath (Join-Path $testDir 'before-source.json') -Raw|ConvertFrom-Json);$testAfter=@(Get-Content -LiteralPath (Join-Path $testDir 'after-source.json') -Raw|ConvertFrom-Json)
 $checks=@();for($i=0;$i -lt $SourcePaths.Count;$i++){$path=$SourcePaths[$i];$commitPath="integration-service/$path";$pinBlob=& git -C $cwd rev-parse "$sourcePin`:$commitPath";$headBlob=& git -C $cwd rev-parse "$expectedHead`:$commitPath";if($LASTEXITCODE -ne 0){throw "commit-blob-lookup-failed:$path"};$records=@($srcBefore[$i],$srcAfter[$i],$testBefore[$i],$testAfter[$i]);if(($records|Where-Object {$_.path -ne $path -or $_.git_blob -ne $pinBlob.Trim() -or $_.git_blob -ne $headBlob.Trim()}).Count -gt 0){throw "source-pin-binding-failed:$path"};if(($records|Select-Object -ExpandProperty sha256 -Unique).Count -ne 1 -or ($records|Select-Object -ExpandProperty git_blob -Unique).Count -ne 1){throw "source-snapshot-drift:$path"};$checks+=4}
 $testText=[IO.File]::ReadAllText((Join-Path $testDir 'stdout.txt'));$loadMatches=[regex]::Matches($testText,'NODE_MODULE_LOAD_RECORD (\{[^\r\n]*?\})(?:\\n|\r?\n|$)');$crashMatches=[regex]::Matches($testText,'NODE_CHILD_CRASH pid=(\d+) phase=(before|after)-aggregate-commit run_id=([0-9a-f-]+) attempt_id=([0-9a-f-]+) source_pk=(\S+) signal=(\S+)');$loads=@(foreach($m in $loadMatches){$m.Groups[1].Value|ConvertFrom-Json});$crashes=@(foreach($m in $crashMatches){[pscustomobject]@{pid=[int]$m.Groups[1].Value;phase=$m.Groups[2].Value;run_id=$m.Groups[3].Value;attempt_id=$m.Groups[4].Value;source_pk=$m.Groups[5].Value;signal=$m.Groups[6].Value}})
 if($loads.Count -ne 2 -or $crashes.Count -ne 2){throw "runtime-event-count-loads=$($loads.Count)-crashes=$($crashes.Count)"};$expectedPath=[string]$bm.output.path;$expectedPath=$expectedPath.Replace('\','/').TrimStart('/');$runtime=@(foreach($load in $loads){$c=@($crashes|Where-Object pid -eq $load.pid);if($c.Count -ne 1){throw "pid-event-join-failed:$($load.pid)"};$event=$c[0];if($load.build_capture_id -ne $bm.capture_id -or $load.module_sha256 -ne $bm.output.sha256 -or [int64]$load.module_size -ne [int64]$bm.output.size -or $load.module_path.Replace('\','/').TrimStart('/') -ne $expectedPath -or $event.phase -notin @('before','after') -or $event.run_id -ne $load.run_id -or $event.attempt_id -notmatch '^[0-9a-f-]{36}$' -or $event.source_pk -ne 'C-REC-4' -or $event.signal -ne 'SIGKILL'){throw "runtime-bytes-or-event-binding-failed:$($load.pid)"};[pscustomobject]@{pid=$load.pid;phase=$event.phase;run_id=$load.run_id;attempt_id=$event.attempt_id;source_pk=$event.source_pk;signal=$event.signal;module_path=$load.module_path;module_sha256=$load.module_sha256;module_size=$load.module_size;build_capture_id=$load.build_capture_id;manifest_sha256=$manifestDigest}})
 if(@($runtime.phase|Sort-Object -Unique).Count -ne 2 -or @($runtime.run_id|Sort-Object -Unique).Count -ne 1 -or @($runtime.attempt_id|Sort-Object -Unique).Count -ne 1){throw 'runtime-event-cohort-mismatch'}
 $pidObs=@(foreach($item in $runtime){$p=Get-Process -Id $item.pid -ErrorAction SilentlyContinue;if($null -ne $p){throw "child-pid-still-present:$($item.pid)"};[pscustomobject]@{pid=$item.pid;observed_absent_utc=[DateTime]::UtcNow.ToString('o');meaning='later read-only absence observation; not an exit timestamp'}})
 $verification=[ordered]@{result='PASS';verified_at_utc=[DateTime]::UtcNow.ToString('o');actual_head=$headBefore;product_source_pin=$sourcePin;build_capture_id=$bm.capture_id;build_command_capture=[IO.Path]::GetFullPath((Join-Path $buildDir 'command.json'));build_output_manifest_path=[IO.Path]::GetFullPath($bmPath);build_output_manifest_sha256=$manifestDigest;build_finished_utc=$bm.build_finished_utc;test_started_utc=$tc.started_utc;output=$bm.output;source_snapshot_equalities=$checks;source_file_count=$SourcePaths.Count;source_records_across_build_test=(4*$SourcePaths.Count);runtime_imports=$runtime;pid_absence_observations=$pidObs;test_exit_code=$tc.exit_code;test_stdout_path=[IO.Path]::GetFullPath((Join-Path $testDir 'stdout.txt'))}
 $verification|ConvertTo-Json -Depth 8|Set-Content -LiteralPath (Join-Path $out 'runtime-binding-verification.json') -Encoding utf8
} catch { $failure=$_.Exception.Message;$exit=1 }
$ownAfter=Snap 'after';$headAfter=Head;$finished=[DateTime]::UtcNow.ToString('o');$stdout=if($verification){$verification|ConvertTo-Json -Depth 8}else{"VERIFICATION_FAILED $failure"};[IO.File]::WriteAllText((Join-Path $out 'stdout.txt'),$stdout,[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText((Join-Path $out 'stderr.txt'),$(if($failure){$failure}else{''}),[Text.UTF8Encoding]::new($false));$cmd=[ordered]@{kind='Verification';capture_id=(Split-Path -Leaf $RunRoot);cwd=$cwd;evidence_root=$RunRoot;command='Verify persisted build manifest against focused Node child imports and source snapshots';started_utc=$start;finished_utc=$finished;actual_head_before=$headBefore;actual_head_after=$headAfter;exit_code=$exit;stdout=(Join-Path $out 'stdout.txt');stderr=(Join-Path $out 'stderr.txt');build_capture_dir=$BuildCaptureDir;test_capture_dir=$TestCaptureDir};$cmd|ConvertTo-Json -Depth 6|Set-Content -LiteralPath (Join-Path $out 'command.json') -Encoding utf8;"CAPTURED verify exit=$exit HEAD=$headBefore";Get-Content -LiteralPath (Join-Path $out 'stdout.txt');if($failure){[Console]::Error.WriteLine($failure)};exit $exit
